// Escolhe a próxima página a escrever e monta o prompt.
// Ordem de prioridade: o PRD manda terminar as páginas-pilar antes de produzir em massa
// (§90), então respeitamos essa fila em vez de varrer o site inteiro.
//
// 2026-09-13 — silo por curso. O portal disputa a cauda longa INFORMACIONAL por curso
// (exemplo, etapas I/II/III, relatório final) e manda o leitor para a categoria do
// curso no Apostileiros. A cauda TRANSACIONAL ("pronto", "pdf", "modelo", marca da
// faculdade) é da loja — nunca escrever página para ela aqui.

const cfg = $('Configuração').first().json;
const paginas = $('Listar páginas').all().map(i => i.json);
const publicado = $('Conteúdo publicado').first().json;

const CURSOS = {
  'pedagogia': 'Pedagogia', 'enfermagem': 'Enfermagem', 'administracao': 'Administração',
  'analise-e-desenvolvimento-de-sistemas': 'Análise e Desenvolvimento de Sistemas', 'direito': 'Direito',
  'biomedicina': 'Biomedicina', 'ciencias-contabeis': 'Ciências Contábeis',
  'servico-social': 'Serviço Social', 'recursos-humanos': 'Recursos Humanos',
};
// nome curto para caber no título de 65 caracteres
const CURTO = { 'analise-e-desenvolvimento-de-sistemas': 'ADS' };

// O risco que organiza cada curso (o mesmo que estruturou os hubs) — o exemplo e o
// relatório precisam respeitar esse limite, senão o portal ensina a fazer errado.
const RISCO = {
  'pedagogia': 'confundir a extensão com aula ou estágio; a ação precisa ter público real fora da sala e cuidado com autorização e imagem de criança',
  'enfermagem': 'informar não é atender: o estudante orienta e educa em saúde, nunca faz procedimento, triagem ou conduta clínica',
  'administracao': 'quem se beneficia: a ação não pode virar consultoria de graça para um único dono de negócio; público e entrega coletiva',
  'analise-e-desenvolvimento-de-sistemas': 'o sistema que ninguém mantém: preferir entrega que sobrevive sem o estudante (capacitação, material, protótipo documentado) e cuidado com dados pessoais',
  'direito': 'a pergunta individual inevitável: o estudante informa direitos e encaminha, nunca dá consultoria nem opina sobre caso concreto',
  'biomedicina': 'a prática do curso não cabe fora do laboratório: nada de diagnóstico, coleta ou exame; a ação é educativa e de popularização científica',
  'ciencias-contabeis': 'o limite da orientação fiscal: educação financeira e tributária coletiva, sem escrituração nem serviço privativo do contador',
  'servico-social': 'não ocupar o lugar do serviço: informar sobre direitos e territórios sem atender caso, sem prometer benefício',
  'recursos-humanos': 'não prometer emprego: currículo, entrevista simulada e orientação sem coletar dado pessoal nem criar expectativa de vaga',
};

// Correspondência etapa → programa observada nos roteiros de um grupo educacional
// (Unopar/Anhanguera) em setembro de 2026, lida nas páginas de produto da loja parceira.
// É "costuma", nunca regra: varia por instituição, matriz e período letivo (§20).
const PROGRAMAS = {
  'Contexto à Comunidade': 'ações ligadas ao contexto social imediato da comunidade: diagnóstico de uma necessidade local e resposta educativa ou organizativa a ela',
  'Inovação e Empreendedorismo': 'contribuições a problemas do contexto social e ao desenvolvimento local, com foco em inovação, geração de renda e organização de pequenos negócios ou iniciativas',
  'Sustentabilidade': 'relação da comunidade com o ambiente natural e construído: educação ambiental, redução de impactos socioambientais e cultura de cuidado',
  'Ação e Difusão Cultural': 'valorização, produção e circulação de cultura, memória e conhecimento junto à comunidade',
};
const ETAPAS = {
  'pedagogia': { 'II': 'Sustentabilidade' },
  'enfermagem': { 'I': 'Ação e Difusão Cultural', 'II': 'Ação e Difusão Cultural', 'III': 'Sustentabilidade', 'IV': 'Inovação e Empreendedorismo' },
  'administracao': { 'I': 'Contexto à Comunidade', 'II': 'Inovação e Empreendedorismo', 'III': 'Sustentabilidade' },
  'analise-e-desenvolvimento-de-sistemas': { 'I': 'Contexto à Comunidade', 'II': 'Ação e Difusão Cultural' },
  'direito': { 'I': 'Ação e Difusão Cultural', 'II': 'Inovação e Empreendedorismo', 'III': 'Sustentabilidade', 'IV': 'Contexto à Comunidade' },
  'biomedicina': { 'I': 'Sustentabilidade', 'II': 'Inovação e Empreendedorismo', 'III': 'Contexto à Comunidade' },
  'ciencias-contabeis': { 'II': 'Inovação e Empreendedorismo', 'III': 'Sustentabilidade' },
  'servico-social': { 'I': 'Ação e Difusão Cultural', 'II': 'Inovação e Empreendedorismo', 'III': 'Contexto à Comunidade' },
  'recursos-humanos': { 'II': 'Inovação e Empreendedorismo' },
};

// Ordem: um silo por vez, do curso com mais busca para o de menos. Dentro do silo,
// exemplo → etapas → relatório final.
const ORDEM_CURSOS = ['pedagogia', 'enfermagem', 'administracao', 'direito', 'ciencias-contabeis',
                      'recursos-humanos', 'servico-social', 'biomedicina', 'analise-e-desenvolvimento-de-sistemas'];
const TEMAS_SILO = ['exemplo', 'etapas', 'relatorio-final'];

const PRIORIDADE = [
  'projeto-de-extensao', 'relatorio-final', 'anhanguera', 'unopar',
  'relatorio-final/como-preencher', 'relatorio-final/durante-a-acao',
  'relatorio-final/resultado-da-acao', 'relatorio-final/conclusao',
  'relatorio-final/percepcao', 'relatorio-final/depoimento-instituicao',
  'relatorio-final/evidencias',
  'como-fazer-projeto-de-extensao', 'ideias-projeto-de-extensao',
  'ods', 'onde-realizar', 'evidencias',
  'pedagogia', 'enfermagem', 'administracao', 'analise-e-desenvolvimento-de-sistemas', 'direito',
  ...ORDEM_CURSOS.flatMap(c => TEMAS_SILO.map(t => `cursos/${c}/${t}`)),
];

// Termo que cada página P0 precisa disputar. Sem fixar isso, o modelo reescreve o
// título com um sinônimo e a página perde a consulta principal (aconteceu com
// /relatorio-final/, que virou "relatório final de extensão").
const PALAVRA_CHAVE = {
  'projeto-de-extensao': 'projeto de extensão',
  'relatorio-final': 'relatório final de atividades extensionistas',
  'relatorio-final/como-preencher': 'como preencher o relatório final de extensão',
  'relatorio-final/durante-a-acao': 'durante a ação projeto de extensão',
  'relatorio-final/resultado-da-acao': 'resultado da ação projeto de extensão',
  'relatorio-final/conclusao': 'conclusão do projeto de extensão',
  'relatorio-final/percepcao': 'percepção das atividades extensionistas',
  'relatorio-final/depoimento-instituicao': 'depoimento da instituição projeto de extensão',
  'relatorio-final/evidencias': 'evidências no relatório final de extensão',
  'como-fazer-projeto-de-extensao': 'como fazer projeto de extensão',
  'ideias-projeto-de-extensao': 'ideias para projeto de extensão',
  'ods': 'ODS no projeto de extensão',
  'onde-realizar': 'onde realizar projeto de extensão',
  'evidencias': 'evidências do projeto de extensão',
  'anhanguera': 'projeto de extensão Anhanguera',
  'unopar': 'projeto de extensão Unopar',
};
for (const c of Object.keys(CURSOS)) {
  const nome = CURTO[c] || CURSOS[c];
  PALAVRA_CHAVE[`cursos/${c}/ideias`] = `temas ideias projeto de extensão ${nome}`;
  PALAVRA_CHAVE[`cursos/${c}/exemplo`] = `exemplo de projeto de extensão ${nome}`;
  PALAVRA_CHAVE[`cursos/${c}/etapas`] = `projeto de extensão I II III ${nome}`;
  PALAVRA_CHAVE[`cursos/${c}/relatorio-final`] = `relatório final projeto de extensão ${nome}`;
}

const porSlug = Object.fromEntries(paginas.map(p => [p.slug, p]));
let alvo = null;

if (cfg.alvo) {
  alvo = porSlug[cfg.alvo];
  if (!alvo) throw new Error(`A página "${cfg.alvo}" não existe no CMS. Crie-a primeiro no painel.`);
} else {
  for (const slug of PRIORIDADE) {
    const p = porSlug[slug];
    if (p && p.words < cfg.minPalavras) { alvo = p; break; }
  }
}
if (!alvo) {
  // A fila de prioridade acabou — as páginas-pilar já passaram do mínimo. Mas o site
  // ainda tem stubs no ar (os ~160 palavras de /como-tirar-fotos.../ e das páginas de
  // ideias por curso), que a lista PRIORIDADE nunca cita. Em vez de parar de produzir,
  // caímos para a fila geral: qualquer página abaixo do mínimo, da mais curta primeiro.
  const restantes = paginas
    .filter(p => p.words < cfg.minPalavras)
    .sort((a, b) => a.words - b.words || a.slug.localeCompare(b.slug));
  alvo = restantes[0] || null;
}
if (!alvo) return [{ json: { nada: true, motivo: 'Todas as páginas do site já passaram do mínimo de palavras.' } }];

// Estrutura pedida pelo PRD, por tipo de página.
const ROTEIRO = {
  guide: ['O que é / resposta direta', 'Para que serve', 'Como funciona na prática',
          'Como escolher (problema, público, local)', 'Passo a passo', 'Exemplo completo identificado como exemplo',
          'Erros comuns', 'Como isso aparece no relatório final', 'Próximos passos'],
  course: ['Como funciona um projeto de extensão neste curso', 'Competências do curso que podem ser aplicadas',
           'Problemas que o curso consegue enfrentar', 'Locais adequados', 'Públicos possíveis',
           'ODS relacionados e por quê', 'Exemplos de atividades', 'Materiais necessários',
           'Evidências que fazem sentido', 'O que muda no relatório final', 'Erros comuns'],
  institution: ['Como funcionam as atividades extensionistas nesta instituição',
                'Como interpretar o roteiro da disciplina', 'Estrutura normalmente solicitada',
                'ODS', 'Comunidade externa e local da atividade', 'Execução',
                'Relatório final', 'Evidências', 'Principais dúvidas', 'Erros recorrentes'],
};

// Guias do silo de curso: cada tema tem roteiro e ângulo PRÓPRIOS. O molde genérico
// de 9 seções é o que fazia toda página parecer a mesma (lição do Sprint C).
const silo = alvo.slug.match(/^cursos\/([a-z0-9-]+)\/([a-z0-9-]+)$/);
const cursoSlug = silo ? silo[1] : null;
const temaSilo = silo ? silo[2] : null;
const nomeCurso = cursoSlug ? CURSOS[cursoSlug] : null;
let roteiro = ROTEIRO[alvo.kind] || ROTEIRO.guide;
let briefing = '';

if (cursoSlug && temaSilo === 'exemplo') {
  roteiro = ['Contexto e problema observado (por que essa ação e não outra)', 'Público e local, e como se chegou até eles',
             'Objetivo geral e objetivos específicos, escritos como o roteiro costuma pedir', 'Justificativa ligada ao curso',
             'Metodologia: o que foi feito, em que ordem, com que material', 'Cronograma realista de uma disciplina',
             'Evidências reunidas (e as que NÃO se deve produzir)', 'Resultado da ação e como medi-lo sem inflar',
             'Percepção do estudante: o que se aprende escrevendo', 'Como adaptar este exemplo ao seu roteiro'];
  briefing = [
    `Esta página é UM exemplo fictício e completo de projeto de extensão em ${nomeCurso}, comentado seção por seção.`,
    'Escolha UMA ideia e a desenvolva do início ao fim — não faça lista de ideias (a página /cursos/' + cursoSlug + '/ideias/ já é a lista).',
    'Abra o exemplo declarando que é fictício e, em cada seção, primeiro mostre o TRECHO do exemplo (como o estudante escreveria) e depois o COMENTÁRIO (por que está assim, o que o roteiro costuma cobrar, o erro comum ali).',
    `Limite profissional que o exemplo precisa respeitar: ${RISCO[cursoSlug]}.`,
    'Não reexplique o que é extensão nem como se faz um projeto em geral: isso mora em /projeto-de-extensao/ e /como-fazer-projeto-de-extensao/ — cite e siga.',
    'Nomes de pessoas, escola, bairro e números do exemplo são inventados de propósito e devem ser apresentados assim.',
  ].join('\n');
}
if (cursoSlug && temaSilo === 'etapas') {
  const mapa = ETAPAS[cursoSlug] || {};
  const linhas = Object.entries(mapa).map(([e, p]) => `  - Projeto de Extensão ${e}: costuma vincular-se ao Programa de ${p}`);
  roteiro = ['O que significam I, II, III (e IV): etapas de uma mesma trilha, não disciplinas soltas',
             'Os programas de extensão e o que cada um pede', `Etapa por etapa em ${nomeCurso}: programa, tipo de ação e o que muda`,
             'Como descobrir a SUA etapa e o SEU programa no roteiro (o que conferir antes de escolher a ação)',
             'Ações que cabem em cada programa neste curso (com público e entrega)', 'O que muda no relatório de uma etapa para outra',
             'Erros comuns: repetir a ação da etapa anterior, escolher ação fora do programa, confundir componente curricular',
             'Perguntas que o leitor faz na busca (responda uma a uma)', 'Próximos passos'];
  briefing = [
    `Esta página responde a quem busca "projeto de extensão II ${nomeCurso}", "projeto de extensão I ${nomeCurso}" etc.: o estudante quer saber o que é a etapa, a que programa ela se liga e como fazer a ação daquela etapa.`,
    'FATOS que você pode usar (observados em roteiros de um grupo educacional em setembro de 2026; escreva sempre "costuma", "em roteiros recentes", e mande conferir no roteiro da disciplina, porque varia por instituição, matriz e período letivo):',
    ...linhas,
    'Programas e o que cada um pede:',
    ...Object.entries(PROGRAMAS).map(([p, d]) => `  - Programa de ${p}: ${d}`),
    'Etapas sem correspondência acima: diga que o programa consta no roteiro e ensine a localizar (nome do componente curricular, campo "programa de extensão"). NÃO invente a correspondência.',
    'NÃO afirme quantidade de horas, semestre, prazo, nota ou campo obrigatório como fato.',
    `Limite profissional do curso: ${RISCO[cursoSlug]}.`,
    'Não reexplique o que é extensão em geral (mora em /projeto-de-extensao/).',
  ].join('\n');
}
if (cursoSlug && temaSilo === 'relatorio-final') {
  roteiro = [`O que muda no relatório final quando o curso é ${nomeCurso} (resposta direta)`,
             'O que conta como RESULTADO neste curso (e o que parece resultado mas não é)',
             'Evidências que fazem sentido aqui — e as que expõem pessoas ou ultrapassam o papel do estudante',
             'Como descrever a ação sem ultrapassar o limite profissional do curso', 'Como ligar a ação às competências do curso sem inventar',
             'Como escrever a percepção sem cair no genérico', 'Erros que mais derrubam o relatório neste curso',
             'Trecho de exemplo (fictício) de duas seções do relatório', 'Checklist final e próximos passos'];
  briefing = [
    `Esta página é ESPECÍFICA de ${nomeCurso}: o que muda no relatório final por causa do curso.`,
    'Os campos do relatório em si (durante a ação, resultado da ação, conclusão, percepção, evidências, depoimento) JÁ têm página própria no cluster /relatorio-final/ — cite e linke, não reexplique o campo. Aqui só entra o que é diferente por ser este curso.',
    `Limite profissional que organiza tudo: ${RISCO[cursoSlug]}.`,
    'Não afirme campo obrigatório, prazo ou nota como fato; o roteiro da disciplina manda.',
  ].join('\n');
}

// Para as páginas de faculdade, mandamos o texto da OUTRA faculdade junto com a ordem
// explícita de não repetir — é o problema nomeado no §22 do PRD.
let contraste = '';
if (alvo.kind === 'institution') {
  const irmas = paginas.filter(p => p.kind === 'institution' && p.slug !== alvo.slug).map(p => p.slug);
  contraste = `\nEstas outras páginas de faculdade já existem: ${irmas.join(', ')}. `
    + `NÃO reaproveite parágrafos, exemplos ou justificativas delas. O conteúdo textual precisa ser próprio desta instituição.`;
}
// Guias do silo: as irmãs do mesmo tema em outros cursos são a armadilha de paráfrase.
if (cursoSlug) {
  const irmas = paginas.filter(p => p.slug.startsWith('cursos/') && p.slug.endsWith('/' + temaSilo) && p.slug !== alvo.slug && p.words > 300).map(p => p.slug);
  if (irmas.length) contraste += `\nJá existem páginas do mesmo tema para outros cursos (${irmas.join(', ')}). NÃO reaproveite a estrutura de frase nem os exemplos delas: o que faz esta página valer é o que só vale para ${nomeCurso}.`;
}

const guiaAtual = (publicado.guides || []).find(g => g.slug === alvo.slug);
const conteudoAtual = guiaAtual
  ? `\n\nCONTEÚDO ATUAL DESTA PÁGINA (amplie e aprofunde, não jogue fora o que está bom):\n`
    + `Resposta rápida: ${guiaAtual.quickAnswer}\n`
    + (guiaAtual.sections || []).map(s => `## ${s.title}\n${(s.paragraphs || []).join('\n')}`).join('\n')
  : '';

// related só pode apontar para GUIA publicado: rascunho vira link 404 no ar, e o
// componente de relacionados só resolve guias (curso e faculdade viram silêncio).
const slugsDisponiveis = paginas.filter(p => p.published !== false && p.kind === 'guide').map(p => `${p.slug} (${p.title})`).join('\n');

const system = [
  'Você é redator do Extensão Fácil, um portal brasileiro que orienta estudantes de graduação a planejar,',
  'executar e documentar atividades de extensão universitária.',
  '',
  'REGRAS EDITORIAIS OBRIGATÓRIAS:',
  '1. Português do Brasil, tom editorial e direto. Nada de linguagem publicitária ou promessa de resultado fácil.',
  '2. NUNCA afirme regra institucional específica (prazo, quantidade de horas, campo obrigatório, nota) como se fosse',
  '   fato verificado. Quando o assunto for exigência de faculdade, diga que varia por curso, matriz e período letivo,',
  '   e oriente a consultar o roteiro oficial no ambiente acadêmico do aluno.',
  '3. Exemplos são bem-vindos, mas todo exemplo deve estar explicitamente identificado como exemplo fictício.',
  '   Jamais apresente um exemplo como atividade real já realizada.',
  '4. Não invente estatística, pesquisa, número ou citação. Se não tem fonte, não afirme.',
  '5. Não escreva texto genérico que serviria para qualquer página. Cada seção precisa ser específica ao tema.',
  '6. Não copie estrutura de frase nem parágrafos de outras páginas do portal.',
  '7. Nada de CTA comercial no meio do conteúdo. Nunca escreva "modelo pronto", "pdf pronto", "baixar" ou nome de',
  '   faculdade como promessa: a cauda transacional é da loja parceira, não deste portal.',
  '8. O leitor típico cumpre uma DISCIPLINA de extensão e recebe um roteiro no ambiente acadêmico.',
  '   Não presuma edital, bolsa, orientador designado ou submissão a comitê — isso é outro contexto.',
  '',
  'FORMATO DA RESPOSTA: apenas um objeto JSON válido, sem markdown, sem crase, sem comentário antes ou depois.',
].join('\n');

const chave = PALAVRA_CHAVE[alvo.slug] || '';

const user = [
  `Escreva o conteúdo completo da página "${alvo.title || alvo.slug}" (${alvo.route}).`,
  `Tipo: ${alvo.kind}. Intenção de busca: ${alvo.intent}.`,
  chave ? `PALAVRA-CHAVE PRINCIPAL: "${chave}". Todas essas palavras precisam aparecer no "title" e na "quickAnswer" — não troque por sinônimo. Pode intercalar outras palavras para o título ficar natural: "Durante a ação: o que escrever no projeto de extensão" é melhor que grudar a expressão inteira no começo.` : '',
  nomeCurso && CURTO[cursoSlug] ? `No título use a sigla "${CURTO[cursoSlug]}"; no texto, escreva o nome completo "${nomeCurso}" pelo menos três vezes.` : '',
  'O "title" segue o padrão do português: maiúscula só na primeira palavra e em nomes próprios. Depois de dois-pontos, continue em MINÚSCULA. NÃO escreva Em Caixa Alta Cada Palavra.',
  briefing ? `\nBRIEFING DESTA PÁGINA:\n${briefing}\n` : '',
  `Mínimo de ${cfg.minPalavras} palavras no total, distribuídas nas seções.`,
  `Escreva pelo menos ${cfg.minSecoes} seções, seguindo este roteiro (adapte os títulos, não copie literalmente):`,
  roteiro.map((s, i) => `  ${i + 1}. ${s}`).join('\n'),
  contraste,
  '',
  'Inclua de 4 a 6 perguntas frequentes no campo "faq", escritas como o leitor digita na busca, cada resposta com 2 ou 3 frases que se sustentem sozinhas.',
  'Escolha de 3 a 4 slugs desta lista para o campo "related" (só slugs que existem aqui):',
  slugsDisponiveis,
  conteudoAtual,
  '',
  'Responda com este JSON:',
  JSON.stringify({
    title: 'título da página, até 65 caracteres, com a palavra-chave principal',
    description: 'meta description entre 120 e 160 caracteres',
    eyebrow: 'chapéu curto, 1 a 3 palavras',
    quickAnswer: 'parágrafo único de 250 a 500 caracteres respondendo a dúvida de forma direta',
    tags: ['3 a 6 tags'],
    related: ['slug1', 'slug2', 'slug3'],
    sections: [{ title: 'título da seção', paragraphs: ['parágrafo'], bullets: ['item opcional'] }],
    faq: [{ q: 'pergunta como o leitor digita', a: 'resposta em 2 ou 3 frases' }],
    sources: [{ institution: 'órgão ou instituição', title: 'nome do documento', url: 'https://', accessedAt: '2026-08-21' }],
  }, null, 2),
  '',
  'O campo "sources" só deve conter fontes que você tem certeza que existem. Se não tiver, devolva lista vazia.',
].join('\n');

return [{ json: { alvo, system, user, cfg, chave } }];

// Portão de qualidade. O PRD (§64) exige revisão antes de publicar; aqui rejeitamos
// o que claramente não passa, para não gravar lixo no banco.

const resposta = $json.choices?.[0]?.message?.content;
if (!resposta) throw new Error('O redator (' + ($json.model || 'sem model') + ') não devolveu conteúdo: ' + JSON.stringify($json).slice(0, 500));

const alvo = $('Escolher alvo e montar prompt').first().json.alvo;
const cfg = $('Configuração').first().json;
const publicado = $('Conteúdo publicado').first().json;
const paginas = $('Listar páginas').all().map(i => i.json);

// O modelo às vezes embrulha o JSON em bloco de código, mesmo proibido no prompt.
let bruto = resposta.trim();
const cerca = bruto.match(/```(?:json)?\s*([\s\S]*?)```/);
if (cerca) bruto = cerca[1].trim();
const inicio = bruto.indexOf('{');
const fim = bruto.lastIndexOf('}');
if (inicio < 0 || fim < 0) throw new Error('Resposta sem JSON reconhecível: ' + bruto.slice(0, 300));

let art;
try { art = JSON.parse(bruto.slice(inicio, fim + 1)); }
catch (e) { throw new Error('JSON inválido do modelo: ' + e.message + ' | trecho: ' + bruto.slice(0, 300)); }

const problemas = [];

// A palavra-chave precisa sobreviver ao título, senão a página não disputa a consulta.
const semAcento = (t) => (t || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const chave = $('Escolher alvo e montar prompt').first().json.chave;
if (chave) {
  // Exigir a frase colada empurrava o título para uma construção artificial. Basta que
  // todas as palavras da chave estejam presentes: o título fica natural e a página
  // continua disputando a consulta.
  const t = semAcento(art.title);
  const faltando = semAcento(chave).split(/\s+/).filter(w => w.length > 2 && !t.includes(w));
  if (faltando.length) problemas.push(`o título não contém ${faltando.map(w => `"${w}"`).join(', ')} da palavra-chave "${chave}"`);
}
const secoes = Array.isArray(art.sections) ? art.sections : [];
const textos = secoes.flatMap(s => [...(s.paragraphs || []), ...(s.bullets || [])]);
const palavras = [art.quickAnswer, ...secoes.map(s => s.title), ...textos].join(' ').trim().split(/\s+/).filter(Boolean).length;

if (!art.title) problemas.push('sem título');
if (!art.description || art.description.length < 80) problemas.push('description curta demais');
if (art.description && art.description.length > 200) problemas.push('description longa demais');
if (!art.quickAnswer || art.quickAnswer.length < 180) problemas.push('resposta rápida curta demais');
if (secoes.length < cfg.minSecoes) problemas.push(`só ${secoes.length} seções (mínimo ${cfg.minSecoes})`);
if (palavras < cfg.minPalavras) problemas.push(`só ${palavras} palavras (mínimo ${cfg.minPalavras})`);
if (secoes.some(s => !s.title || !(s.paragraphs || []).length)) problemas.push('seção sem título ou sem parágrafo');

// Marcas de rascunho que o modelo às vezes deixa
const suspeito = /lorem ipsum|\[inserir|\bXXX\b|preencher aqui|TODO:/i;
if (suspeito.test(JSON.stringify(art))) problemas.push('sobrou texto de preenchimento');

// §25/§22: nenhum parágrafo longo pode ser idêntico ao de outra página já publicada
const corpus = [];
for (const g of publicado.guides || []) {
  if (g.slug === alvo.slug) continue;
  for (const s of g.sections || []) for (const p of s.paragraphs || []) corpus.push({ slug: g.slug, p });
}
for (const p of textos) {
  if (p.length < 120) continue;
  const igual = corpus.find(c => c.p.trim() === p.trim());
  if (igual) { problemas.push(`parágrafo idêntico ao de /${igual.slug}/`); break; }
}

// related só pode apontar para slug que existe E está publicado — link para rascunho
// vira 404 no ar (os stubs do silo por curso nascem published=false)
const existentes = new Set(paginas.filter(p => p.published !== false).map(p => p.slug));
const related = (art.related || []).filter(s => existentes.has(s) && s !== alvo.slug).slice(0, 4);
if (!related.length) problemas.push('nenhum link interno válido');

// FAQ: sai no bloco visível e no FAQPage do JSON-LD (mesmo dado). Só pares completos.
const faq = (Array.isArray(art.faq) ? art.faq : [])
  .filter(f => f && typeof f.q === 'string' && typeof f.a === 'string' && f.q.trim() && f.a.trim().length >= 40)
  .map(f => ({ q: f.q.trim(), a: f.a.trim() })).slice(0, 8);
if (faq.length < 3) problemas.push(`só ${faq.length} perguntas frequentes válidas (mínimo 3)`);

if (problemas.length) {
  throw new Error(`Conteúdo reprovado para ${alvo.route}: ${problemas.join('; ')}`);
}

return [{
  json: {
    slug: alvo.slug,
    kind: alvo.kind,
    title: art.title,
    description: art.description,
    eyebrow: art.eyebrow || alvo.eyebrow || '',
    quickAnswer: art.quickAnswer,
    intent: alvo.intent,
    tags: (art.tags || []).slice(0, 6),
    related,
    extra: alvo.extra || {},
    author: 'equipe-extensao-facil',
    reviewedAt: new Date().toISOString().slice(0, 10),
    // Preserva o estado da página: stub criado como rascunho continua rascunho até
    // alguém publicar no painel (§64); página que já está no ar continua no ar.
    published: alvo.published !== false,
    faq,
    // o modelo devolve bullets: [""] quando não tem item — vira marcador vazio na página
    sections: secoes.map(s => ({ title: s.title, paragraphs: (s.paragraphs || []).filter(p => typeof p === 'string' && p.trim()),
      bullets: (s.bullets || []).filter(b => typeof b === 'string' && b.trim()) })),
    sources: Array.isArray(art.sources) ? art.sources : [],
    _resumo: { rota: alvo.route, palavras, secoes: secoes.length, fontes: (art.sources || []).length, redator: $json.model || '?' },
  },
}];

